// Test block EmptyState (Data): What a list, page or panel shows when it has nothing in it: why it's empty and the one thing to do next.
//
// Generated by tools/blocks_from_app_blocks.py from the App Block card kit/blocks/data/EmptyState.md and its markup
// (kit/blocks/data/EmptyState.html; source 45e808610602), with the vocabulary in
// functional/blocks/spec.json. Do not edit: change the spec (or the App Block) and generate again.
//
// Steps (e2e):
//   Then I see the empty state {title}
//   Then I see no empty state
//   Then the empty state offers {name}
//   When I take the empty state action {name}
//   Then the empty state is in the {state} state
// States (from the card): First run, No match, All done, No permission to create, Inside a small panel, Loading,
// Search with no match. Checked by the state step: First run, All done.
import { Registry } from '../../js/registry.js';
import * as p from '../../js/primitives.js';

export const BLOCK = 'EmptyState';
export const ROUTE = '';
export const STATES = ["First run", "No match", "All done", "No permission to create", "Inside a small panel", "Loading", "Search with no match"];
export const DEFAULT_STATE = 'First run';
export const CHECKED_STATES = ["First run", "All done"];
export const DEMO = ["kit/blocks/data/EmptyState.html"];
export const SELF_TEST = [
  "Then I see the empty state \"No notes yet\"",
  "Then the empty state offers \"New Note\"",
  "Then the empty state offers \"Import from a File\"",
  "Then the empty state is in the \"First run\" state",
  "When I take the empty state action \"New Note\"",
  "Then I see the empty state \"No notes yet\"",
];

export const steps = new Registry({ block: BLOCK });

/** The EmptyState block on a page: its controls, found as a person finds them (role and name, label, text). */
export class EmptyState {
  constructor(page, baseURL = '') {
    this.page = page;
    this.baseURL = baseURL;
  }

  async box() {
    return p.control(this.page, { css: '.empty', block: BLOCK });
  }

  /** Every match, possibly none (for counting). */
  async boxAll() {
    return this.page.locator('.empty');
  }

  async heading() {
    return p.control(await this.box(), { role: 'heading', block: BLOCK });
  }

  async action(name) {
    return p.control(await this.box(), { text: String(name), block: BLOCK });
  }

  async actions() {
    return p.control(await this.box(), { css: 'footer a, footer button', block: BLOCK });
  }

  /** Every match, possibly none (for counting). */
  async actionsAll() {
    return (await this.box()).locator('footer a, footer button');
  }

  /** Check one of the card's states: First run, All done. */
  async expectState(state) {
    const b = this;
    if (state === 'First run') {
      await p.expectVisible((await b.actions()).first());
    } else if (state === 'All done') {
      await p.expectCount(await b.actionsAll(), 0);
    } else {
      throw new Error(`EmptyState has no check for the state '${state}'; checked: ${CHECKED_STATES.join(', ')}`);
    }
  }
}

steps.step("Then I see the empty state {title}", async (world, { title }) => {
  const b = new EmptyState(world.page, world.baseURL ?? '');
  await p.expectText(await b.heading(), String(title));
}, { level: 'e2e' });

steps.step("Then I see no empty state", async (world, _values) => {
  const b = new EmptyState(world.page, world.baseURL ?? '');
  await p.expectCount(await b.boxAll(), 0);
}, { level: 'e2e' });

steps.step("Then the empty state offers {name}", async (world, { name }) => {
  const b = new EmptyState(world.page, world.baseURL ?? '');
  await p.expectVisible(await b.action(name));
}, { level: 'e2e' });

steps.step("When I take the empty state action {name}", async (world, { name }) => {
  const b = new EmptyState(world.page, world.baseURL ?? '');
  await p.click(await b.action(name));
}, { level: 'e2e' });

steps.step("Then the empty state is in the {state} state", async (world, { state }) => {
  const b = new EmptyState(world.page, world.baseURL ?? '');
  await b.expectState(state);
}, { level: 'e2e' });
